  1	/* ============================================================
  2	   views/knowledge.js — Knowledge view
  3	   Section 4f of the MCP Server Dashboard SPA
  4	   Depends on: API, escapeHtml, formatDate, showLoading, showError
  5	   ============================================================ */
  6	
  7	function renderKnowledge(app) {
  8	  showLoading(app);
  9	
 10	  /* ── Confidence bucket thresholds ────────────────────────── */
 11	  var CONFIDENCE_HIGH_MIN   = 68;   /* 68–100 → High  */
 12	  var CONFIDENCE_MEDIUM_MIN = 34;   /* 34–67  → Medium */
 13	  /* 0–33 → Low */
 14	
 15	  /* ── View state ──────────────────────────────────────────── */
 16	  var allInsights        = [];
 17	  var activeTab          = 'global';   /* 'global' | 'repository' */
 18	  var filterCategory     = '';
 19	  var filterRepository   = '';
 20	  var filterQuery        = '';
 21	  var editingId       = null;       /* numeric id of card in edit mode */
 22	  var confirmDeleteId = null;       /* numeric id of card in delete-confirm mode */
 23	  var movingId        = null;       /* numeric id of card in move mode */
 24	
 25	  /* ── formatConfidence ────────────────────────────────────── */
 26	  function formatConfidence(value) {
 27	    var pct = Math.round(value * 100);
 28	    var label;
 29	    if (pct >= CONFIDENCE_HIGH_MIN) {
 30	      label = 'High';
 31	    } else if (pct >= CONFIDENCE_MEDIUM_MIN) {
 32	      label = 'Medium';
 33	    } else {
 34	      label = 'Low';
 35	    }
 36	    return pct + '% (' + label + ')';
 37	  }
 38	
 39	  /* ── applyFilters ────────────────────────────────────────── */
 40	  function applyFilters() {
 41	    var scopeValue = activeTab === 'global' ? 'global' : 'repository';
 42	    return allInsights.filter(function (ins) {
 43	      if (ins.scope !== scopeValue) return false;
 44	      if (filterCategory && ins.category !== filterCategory) return false;
 45	      if (activeTab === 'repository' && filterRepository && ins.repository_name !== filterRepository) return false;
 46	      if (filterQuery) {
 47	        var q = filterQuery.toLowerCase();
 48	        var titleMatch    = ins.title   && ins.title.toLowerCase().indexOf(q) !== -1;
 49	        var contentMatch  = ins.content && ins.content.toLowerCase().indexOf(q) !== -1;
 50	        var tagsMatch     = ins.tags    && ins.tags.some(function (t) { return t.toLowerCase().indexOf(q) !== -1; });
 51	        if (!titleMatch && !contentMatch && !tagsMatch) return false;
 52	      }
 53	      return true;
 54	    });
 55	  }
 56	
 57	  /* ── getDistinctValues ───────────────────────────────────── */
 58	  /* Returns { categories: string[], repositories: string[] } — both arrays are
 59	     sorted alphabetically and contain only distinct non-empty values from
 60	     the provided insights array. */
 61	  function getDistinctValues(insights) {
 62	    var categories   = [];
 63	    var repositories = [];
 64	    insights.forEach(function (ins) {
 65	      if (ins.category        && categories.indexOf(ins.category)               === -1) categories.push(ins.category);
 66	      if (ins.repository_name && repositories.indexOf(ins.repository_name)      === -1) repositories.push(ins.repository_name);
 67	    });
 68	    categories.sort();
 69	    repositories.sort();
 70	    return { categories: categories, repositories: repositories };
 71	  }
 72	
 73	  /* ── buildFilterBarHtml ──────────────────────────────────── */
 74	  function buildFilterBarHtml(categories, repositories) {
 75	    var catOptions = categories.map(function (c) {
 76	      return '<option value="' + escapeHtml(c) + '"' + (filterCategory === c ? ' selected' : '') + '>' + escapeHtml(c) + '</option>';
 77	    }).join('');
 78	
 79	    var baseBar =
 80	      '<label for="kn-category">Category:</label>' +
 81	      '<select id="kn-category" class="form-control form-control-sm">' +
 82	        '<option value="">All categories</option>' + catOptions +
 83	      '</select>' +
 84	      '<label for="kn-query">Search:</label>' +
 85	      '<input id="kn-query" type="text" class="form-control form-control-sm" placeholder="Title, content or tag…" value="' + escapeHtml(filterQuery) + '">';
 86	
 87	    if (activeTab === 'repository') {
 88	      var repoOptions = repositories.map(function (r) {
 89	        return '<option value="' + escapeHtml(r) + '"' + (filterRepository === r ? ' selected' : '') + '>' + escapeHtml(r) + '</option>';
 90	      }).join('');
 91	      return (
 92	        '<label for="kn-repository">Repository:</label>' +
 93	        '<select id="kn-repository" class="form-control form-control-sm">' +
 94	          '<option value="">All repositories</option>' + repoOptions +
 95	        '</select>' +
 96	        baseBar
 97	      );
 98	    }
 99	
100	    return baseBar;

 1	/* ============================================================
 2	   api-client.js — API Client module
 3	   Section 1 of the MCP Server Dashboard SPA
 4	   ============================================================ */
 5	
 6	var API = (function () {
 7	  async function request(method, path, body) {
 8	    var opts = {
 9	      method: method,
10	      headers: {},
11	    };
12	    if (body !== undefined) {
13	      opts.headers['Content-Type'] = 'application/json';
14	      opts.body = JSON.stringify(body);
15	    }
16	    var res = await fetch('/api' + path, opts);
17	    if (!res.ok) {
18	      var errData = null;
19	      try { errData = await res.json(); } catch (_) {}
20	      var errMsg = (errData && errData.error && errData.error.message) || ('HTTP ' + res.status);
21	      var errCode = (errData && errData.error && errData.error.code) || 'ERROR';
22	      throw { code: errCode, message: errMsg };
23	    }
24	    if (res.status === 204) return null;
25	    return res.json();
26	  }
27	
28	  /**
29	   * Serialize *params* as a URL query string.
30	   *
31	   * Keys whose value is `undefined` or an empty string (`''`) are silently
32	   * omitted from the output.  This is intentional: callers use `undefined` as
33	   * a "no filter" sentinel (e.g. `{ wp: wpId }` where `wpId` may be
34	   * `undefined`), and the omission prevents `?wp=undefined` from reaching
35	   * the server.
36	   *
37	   * @param {Record<string, any>|null|undefined} params - Key/value pairs to encode.
38	   * @returns {string} A `?key=value&…` string, or `''` when no params survive
39	   *   the filter.
40	   */
41	  function buildQueryString(params) {
42	    if (!params) return '';
43	    var parts = Object.keys(params)
44	      .filter(function (k) { return params[k] !== undefined && params[k] !== ''; })
45	      .map(function (k) { return encodeURIComponent(k) + '=' + encodeURIComponent(params[k]); });
46	    return parts.length ? '?' + parts.join('&') : '';
47	  }
48	
49	  return {
50	    getProjects: function (params) {
51	      return request('GET', '/projects' + buildQueryString(params));
52	    },
53	    getProject:               function (slug)         { return request('GET',    '/projects/' + encodeURIComponent(slug)); },
54	    getWorkPackages:          function (slug)         { return request('GET',    '/projects/' + encodeURIComponent(slug) + '/work-packages'); },
55	    getWorkPackage:           function (slug, wpId)   { return request('GET',    '/projects/' + encodeURIComponent(slug) + '/work-packages/' + encodeURIComponent(wpId)); },
56	    deleteProject:            function (slug)         { return request('DELETE', '/projects/' + encodeURIComponent(slug)); },
57	    archiveProject:           function (slug)         { return request('POST',   '/projects/' + encodeURIComponent(slug) + '/archive'); },
58	    unarchiveProject:         function (slug)         { return request('POST',   '/projects/' + encodeURIComponent(slug) + '/unarchive'); },
59	    getConfig:                function ()             { return request('GET',    '/config'); },
60	    updateConfig:             function (data)         { return request('PUT',    '/config', data); },
61	    getInsights:              function ()             { return request('GET',    '/insights'); },
62	    getServerInfo:            function ()             { return request('GET',    '/server-info'); },
63	    getPlanDocument:          function (slug)         { return request('GET',    '/projects/' + encodeURIComponent(slug) + '/plan'); },
64	    getSynthesisDocument:     function (slug)         { return request('GET',    '/projects/' + encodeURIComponent(slug) + '/synthesis'); },
65	    analyzeProjectReset:      function (slug)         { return request('POST',   '/projects/' + encodeURIComponent(slug) + '/reset', { dry_run: true }); },
66	    applyProjectReset:        function (slug, decisions) { return request('POST', '/projects/' + encodeURIComponent(slug) + '/reset', { dry_run: false, decisions: decisions }); },
67	    getProjectHealth:         function (slug)         { return request('GET',    '/projects/' + encodeURIComponent(slug) + '/health'); },
68	    getWorkPackageOverview:   function (slug)         { return request('GET',    '/projects/' + encodeURIComponent(slug) + '/work-packages/overview'); },
69	    renameProject:            function (slug, title)  { return request('PATCH',  '/projects/' + encodeURIComponent(slug), { title: title }); },
70	    renameSlug:               function (slug, newSlug) { return request('PATCH',  '/projects/' + encodeURIComponent(slug), { slug: newSlug }); },
71	    markProjectComplete:      function (slug)         { return request('POST',   '/projects/' + encodeURIComponent(slug) + '/complete'); },
72	    getRunLogs:               function (slug)         { return request('GET',    '/projects/' + encodeURIComponent(slug) + '/runs'); },
73	    getRunLogEntries:         function (slug, filename, afterLine) {
74	      var qs = (afterLine !== undefined && afterLine !== null) ? ('?after=' + encodeURIComponent(afterLine)) : '';
75	      return request('GET', '/projects/' + encodeURIComponent(slug) + '/runs/' + encodeURIComponent(filename) + qs);
76	    },
77	    getDialogues: function (slug, wpId) {
78	      return request('GET', '/projects/' + encodeURIComponent(slug) + '/dialogues' + buildQueryString({ wp: wpId }));
79	    },
80	    getDialogueContent: function (slug, filename) {
81	      return request('GET', '/projects/' + encodeURIComponent(slug) + '/dialogues/' + encodeURIComponent(filename))
82	        .then(function (data) { return data.content; });
83	    },
84	    getChunks: function (slug, wpId) {
85	      return request('GET', '/projects/' + encodeURIComponent(slug) + '/chunks' + buildQueryString({ wp: wpId }));
86	    },
87	    getChunkRendered: function (slug, filename) {
88	      return request('GET', '/projects/' + encodeURIComponent(slug) + '/chunks/' + encodeURIComponent(filename) + '/rendered')
89	        .then(function (data) { return data.content; });
90	    },
91	
92	    // -- Orchestrator --------------------------------------------------
93	    orchestratorStart:       function (planPath, dryRun) { return request('POST',   '/orchestrator/start',                                         { planPath: planPath, dryRun: dryRun }); },
94	    orchestratorGetQueue:    function ()                 { return request('GET',    '/orchestrator/queue'); },
95	    orchestratorGetRunStatus: function (slug)            { return request('GET',    '/orchestrator/run-status/' + encodeURIComponent(slug)); },
96	    orchestratorKill:        function (id)               { return request('POST',   '/orchestrator/kill/'       + encodeURIComponent(id)); },
97	    orchestratorDismiss:     function (id)               { return request('POST',   '/orchestrator/dismiss/'    + encodeURIComponent(id)); },
98	
99	    // -- Knowledge -----------------------------------------------------

101	  }
102	
103	  /* ── buildKnowledgeHtml ──────────────────────────────────── */
104	  function buildKnowledgeHtml(insights) {
105	    if (!insights.length) {
106	      return '<p class="text-muted mt-16">No knowledge entries found.</p>';
107	    }
108	
109	    return insights.map(function (ins) {
110	      var id          = ins.id;
111	      var isGlobal    = ins.scope === 'global';
112	      var isEditing   = editingId === id;
113	      var isConfirm   = confirmDeleteId === id;
114	      var isMoving    = movingId === id;
115	
116	      /* ── Scope badge ── */
117	      var scopeBadgeClass = isGlobal ? 'badge badge-scope-global' : 'badge badge-scope-repository';
118	      var scopeLabel      = isGlobal ? 'Global' : 'Repository';
119	
120	      /* ── Tags ── */
121	      var tagsHtml = '';
122	      if (ins.tags && ins.tags.length) {
123	        tagsHtml = ins.tags.map(function (t) {
124	          return '<span class="tag-chip">' + escapeHtml(t) + '</span>';
125	        }).join(' ');
126	      }
127	
128	      /* ── Content preview ── */
129	      var preview = ins.content ? ins.content.slice(0, 200) + (ins.content.length > 200 ? '…' : '') : '';
130	
131	      /* ── Superseded-by notice ── */
132	      var supersededHtml = ins.superseded_by != null
133	        ? '<p class="text-muted" style="font-size:12px">Superseded by KN-' + ins.superseded_by + '</p>'
134	        : '';
135	
136	      /* ── Inline edit form ── */
137	      if (isEditing) {
138	        var tagsValue = ins.tags ? ins.tags.join(', ') : '';
139	        var confPct   = formatConfidence(ins.confidence != null ? ins.confidence : 0);
140	        return '<div class="card" data-id="' + id + '">' +
141	          '<form id="kn-edit-form-' + id + '">' +
142	            '<div class="form-group">' +
143	              '<label class="form-label">Title</label>' +
144	              '<input id="kn-edit-title-' + id + '" class="form-control" type="text" value="' + escapeHtml(ins.title || '') + '">' +
