326	  /* ── wireEvents ──────────────────────────────────────────── */
327	  function wireEvents() {
328	    /* Tab bar */
329	    var tabButtons = document.querySelectorAll('.knowledge-tab');
330	    tabButtons.forEach(function (btn) {
331	      btn.addEventListener('click', function () {
332	        var newTab = this.getAttribute('data-tab');
333	        if (newTab === activeTab) return;
334	        activeTab          = newTab;
335	        filterCategory     = '';
336	        filterRepository   = '';
337	        filterQuery        = '';
338	        editingId       = null;
339	        confirmDeleteId = null;
340	        movingId        = null;
341	
342	        /* Update active class */
343	        tabButtons.forEach(function (b) {
344	          b.classList.toggle('active', b.getAttribute('data-tab') === activeTab);
345	        });
