347	        /* Tab change alters the filter bar layout (repository dropdown appears/
348	           disappears), so rebuild the bar first, then re-render the card list. */
349	        renderFilterBar();
350	        renderList();
351	      });
352	    });
353	
354	    /* Wire filter bar */
355	    var filterBarEl = document.getElementById('kn-filter-bar');
356	    if (filterBarEl) wireFilterBarEvents(filterBarEl);
357	
358	    /* Event delegation for card actions */
359	    var listEl = document.getElementById('knowledge-list');
360	    if (!listEl) return;
361	
362	    listEl.addEventListener('click', function (e) {
363	      var btn = e.target.closest('[data-action]');
364	      if (!btn) return;
365	
366	      var action = btn.getAttribute('data-action');
367	      var rawId  = btn.getAttribute('data-id');
368	      var id     = parseInt(rawId, 10);
369	
370	      if (action === 'edit') {
371	        editingId       = id;
372	        confirmDeleteId = null;
373	        movingId        = null;
374	        renderList();
375	        return;
376	      }
377	
378	      if (action === 'cancel-edit') {
379	        editingId = null;
380	        renderList();
381	        return;
382	      }
383	
384	      if (action === 'delete') {
385	        confirmDeleteId = id;
386	        editingId       = null;
387	        movingId        = null;
388	        renderList();
389	        return;
390	      }
391	
392	      if (action === 'cancel-delete') {
393	        confirmDeleteId = null;
394	        renderList();
395	        return;
396	      }
397	
398	      if (action === 'move') {
399	        movingId        = id;
400	        editingId       = null;

401	        confirmDeleteId = null;
402	        renderList();
403	        return;
404	      }
405	
406	      if (action === 'cancel-move') {
407	        movingId = null;
408	        renderList();
409	        return;
410	      }
