459	    /* Edit form submit — uses event delegation on the list container */
460	    listEl.addEventListener('submit', function (e) {
461	      var form = e.target.closest('form[id^="kn-edit-form-"]');
462	      if (!form) return;
463	      e.preventDefault();
464	
465	      var formId = form.id.replace('kn-edit-form-', '');
466	      var eid    = parseInt(formId, 10);
467	
468	      /* Find insight to get scope/repository_name */
469	      var original = allInsights.find(function (ins) { return ins.id === eid; });
470	      if (!original) return;
471	
472	      var titleEl    = document.getElementById('kn-edit-title-'   + eid);
473	      var contentEl  = document.getElementById('kn-edit-content-' + eid);
474	      var categoryEl = document.getElementById('kn-edit-category-'+ eid);
475	      var tagsEl     = document.getElementById('kn-edit-tags-'    + eid);
476	      var confEl     = document.getElementById('kn-edit-conf-'    + eid);
477	      var msgEl      = document.getElementById('kn-edit-msg-'     + eid);
478	
479	      var rawTags = tagsEl ? tagsEl.value : '';
480	      var tags    = rawTags.split(',').map(function (t) { return t.trim(); }).filter(Boolean);
481	
482	      var updateData = {
483	        title:      titleEl    ? titleEl.value    : original.title,
484	        content:    contentEl  ? contentEl.value  : original.content,
485	        category:   categoryEl ? categoryEl.value : original.category,
486	        tags:       tags,
